function toggleFaq(btn) {
  const item = btn.parentElement;
  const ans = item.querySelector('.faq-a');
  const isOpen = item.classList.contains('open');
  document.querySelectorAll('.faq-item').forEach(i => {
    i.classList.remove('open');
    i.querySelector('.faq-a').style.maxHeight = '0';
  });
  if (!isOpen) {
    item.classList.add('open');
    ans.style.maxHeight = ans.scrollHeight + 'px';
  }
}

// Contact Modal
const contactModal = document.getElementById('contactModal');
const closeBtn = document.getElementById('closeContactModal');
const submitBtn = document.getElementById('submitContact');
const contactForm = document.getElementById('contactForm');
const modalSuccess = document.getElementById('modalSuccess');

function closeModal() {
  contactModal.classList.remove('active');
  contactModal.setAttribute('aria-hidden', 'true');
  document.body.style.overflow = '';
  setTimeout(() => {
    contactForm.style.display = '';
    modalSuccess.style.display = 'none';
    document.getElementById('contactName').value = '';
    document.getElementById('contactEmail').value = '';
    document.getElementById('contactMessage').value = '';
  }, 300);
}

closeBtn.addEventListener('click', closeModal);
contactModal.addEventListener('click', e => { if (e.target === contactModal) closeModal(); });
document.addEventListener('keydown', e => { if (e.key === 'Escape') closeModal(); });

submitBtn.addEventListener('click', () => {
  const name = document.getElementById('contactName');
  const email = document.getElementById('contactEmail');
  const message = document.getElementById('contactMessage');
  let valid = true;
  [name, email, message].forEach(f => f.classList.remove('error'));
  if (!name.value.trim()) { name.classList.add('error'); valid = false; }
  if (!email.value.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)) { email.classList.add('error'); valid = false; }
  if (!message.value.trim()) { message.classList.add('error'); valid = false; }
  if (!valid) return;

  submitBtn.disabled = true;
  submitBtn.textContent = 'שולח...';

  const formData = new FormData();
  formData.append('name', name.value.trim());
  formData.append('email', email.value.trim());
  formData.append('message', message.value.trim());
  formData.append('_subject', 'פנייה חדשה מאתר מתי טסים');

  fetch('https://formspree.io/f/__FORM_WEBSITE__', { method: 'POST', body: formData, headers: { Accept: 'application/json' } }).then(function (r) { if (!r.ok) throw new Error('form'); return r; })
    .then(r => r.json())
    .then(() => {
      contactForm.style.display = 'none';
      modalSuccess.style.display = 'block';
      submitBtn.disabled = false;
      submitBtn.textContent = 'שלח פנייה';
    })
    .catch(() => {
      const subject = encodeURIComponent('פנייה מאתר מתי טסים - ' + name.value.trim());
      const body = encodeURIComponent('שם: ' + name.value.trim() + '\nאימייל: ' + email.value.trim() + '\n\n' + message.value.trim());
      window.location.href = 'mailto:info@mataytasim.co.il?subject=' + subject + '&body=' + body;
      submitBtn.disabled = false;
      submitBtn.textContent = 'שלח פנייה';
      closeModal();
    });
});

